package com.bank.agediversity;

import java.util.*;
import java.util.logging.*;
import static java.util.stream.Collectors.*;

public class MostDiverseDemo {
    private static final Logger log = Logger.getLogger("AgeDiversity");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<Employee> staff = List.of(
            new Employee("Rajesh", "IT", 55),
            new Employee("Amit", "IT", 25),      // IT range = 30
            new Employee("Priya", "Sales", 40),
            new Employee("Neha", "Sales", 35));  // Sales range = 5
        DiversityService service = new DiversityService();

        log.info(() -> "Most age-diverse dept: " + service.mostDiverseDept(staff).orElse("none"));
    }
}

