class Employee {
    private final String name;
    private final String department;
    private final int age;
    Employee(String name, String department, int age) {
        this.name = name; this.department = department; this.age = age;
    }
    String getDepartment() { return department; }
    int getAge() { return age; }
}

// ─── Would be in service/DiversityService.java ───
class DiversityService {
    Optional<String> mostDiverseDept(List<Employee> staff) {
        Map<String, IntSummaryStatistics> statsByDept = staff.stream()
            .collect(groupingBy(Employee::getDepartment,
                summarizingInt(Employee::getAge)));       // min/max/avg per dept, one pass
        return statsByDept.entrySet().stream()
            .max(Comparator.comparingInt(e ->
                e.getValue().getMax() - e.getValue().getMin()))  // widest range wins
            .map(Map.Entry::getKey);
    }
}
